effect.shader:
const float GM_K=1.73205080757;
float gmTri(vec2 p,float r){p.x=abs(p.x)-r;p.y=p.y+r/GM_K;if(p.x+GM_K*p.y>0.0)p=vec2(p.x-GM_K*p.y,-GM_K*p.x-p.y)*0.5;p.x-=clamp(p.x,-2.0*r,0.0);return -length(p)*sign(p.y);}
vec2 gmRotate(vec2 p,float a){float c=cos(a),s=sin(a);return mat2(c,-s,s,c)*p;}
void main(){vec2 uv=acScreenNorm;vec2 texSize=max(inputImg.size,vec2(1.0));float aspect=texSize.x/texSize.y;vec2 p=(uv-center)*vec2(aspect,1.0);p=gmRotate(p,-rotation);float d=gmTri(p,size);float eps=max(size*0.002,0.0002);vec2 grad=normalize(vec2(gmTri(p+vec2(eps,0.0),size)-gmTri(p-vec2(eps,0.0),size),gmTri(p+vec2(0.0,eps),size)-gmTri(p-vec2(0.0,eps),size))+vec2(0.00001));grad=gmRotate(grad,rotation)/vec2(aspect,1.0);float mask=1.0-smoothstep(-feather,feather,d);float depth=clamp(-d/max(size,0.001),0.0,1.0);vec2 refractOffset=grad*refraction*(0.025+0.075*depth);vec2 chroma=grad*dispersionPx/texSize;vec4 src=texture2DCv(inputImg.texture,uv);vec4 rr=texture2DCv(inputImg.texture,clamp(uv+refractOffset+chroma,0.0,1.0));vec4 gg=texture2DCv(inputImg.texture,clamp(uv+refractOffset,0.0,1.0));vec4 bb=texture2DCv(inputImg.texture,clamp(uv+refractOffset-chroma,0.0,1.0));vec3 refracted=vec3(rr.r,gg.g,bb.b);vec2 reflectedUv=clamp(center-(uv-center)+refractOffset*0.35,0.0,1.0);vec3 reflected=texture2DCv(inputImg.texture,reflectedUv).rgb;float fresnel=pow(1.0-clamp(depth,0.0,1.0),3.0);refracted=mix(refracted,reflected,reflection*fresnel);float caustic=exp(-abs(d)/max(feather*2.5,0.0005))*edgeGlow;refracted+=vec3(0.75,0.88,1.0)*caustic;vec3 prism=mix(src.rgb,refracted,mask);gl_FragColor=vec4(mix(src.rgb,prism,mixAmount),src.a);}
